    @Test
    public void displayQRCode(){
        byte[]tdata = {0x30,0x33,0x67};
        byte[]pdata = {0x30,0x33,0x67};
        DiaplayQRImageParameters parameter = new DiaplayQRImageParameters();
        parameter.setLevel(QRErrorCorrectLevel.LEVEL_1);
        parameter.setMask(QRMask.MASK_1);
        parameter.setVersion((byte)0);
        parameter.setAutoCenter(true);
        parameter.setXCoordinate((byte)1);
        parameter.setYCoordinate((byte)1);
        parameter.setPosition(QRTextPosition.BOTTOM);
        parameter.setTextData(tdata);
        try{
            displayModule.displayQRCode(pdata, parameter);
        }catch (NSDKException e) {
            e.printStackTrace();
        }
    }

    @Test
    public void displayColorImage(){
        DisplayListener listener = new DisplayListener() {
            @Override
            public void onError(int i, String s) {
                System.out.println("Display color image error code: " + i);
                System.out.println("Display color image error mesage: " + s);
            }

            @Override
            public void onSuccess() {
                System.out.println("Display color image successfully.");
            }
        };
        byte[] imageData = ISOUtils.hex2byte("");
        try {
            extDisplay.loadImage((byte) 1, imageData, listener);
            Thread.sleep(1000000);
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
